# ===== Result Enums =====
class FailureResult(IntEnum):
    """Possible results returned for failure requests."""

    UNKNOWN = 0
    SUCCESS = 1
    NO_SYSTEM = 2
    CONNECTION_ERROR = 3
    UNSUPPORTED = 4
    DENIED = 5
    DISABLED = 6
    TIMEOUT = 7


class FailureError(MavsdkError):
    """Raised when a Failure request fails.

    Attributes
    ----------
    result : FailureResult
        The result the request failed with.
    origin : str
        The method that failed.
    params : tuple
        The arguments the method was called with.
    """

    def __init__(self, result, origin, *params):
        super().__init__(result, origin, *params)
        self.result = result
        self.origin = origin
        self.params = params

    def __str__(self):
        return f"{self.result.name}; origin: {self.origin}; params: {self.params}"


